package cn.iinti.sekiro3.business.api;

import com.alibaba.fastjson.JSON;
import com.alibaba.fastjson.JSONObject;
import cn.iinti.sekiro3.business.api.interfaze.*;
import okhttp3.*;
import java.net.URLEncoder;
import java.util.List;
import java.util.concurrent.*;

public class RpcClient {
 private static final long HEARTBEAT_INTERVAL_MS=25000L, MAX_MESSAGE_BYTES=10L*1024*1024;
 private final String group,clientId,scheme,host; private final int port; private final String token;
 private final HandlerRegistry handlers=new HandlerRegistry(); private final OkHttpClient httpClient=new OkHttpClient.Builder().build(); private final ScheduledExecutorService scheduler=Executors.newSingleThreadScheduledExecutor(); private final ExecutorService workers=Executors.newCachedThreadPool(); private final java.util.Set<RpcCancellationToken> activeTokens=ConcurrentHashMap.newKeySet(); private final Object lock=new Object(); private volatile WebSocket socket; private volatile boolean connected,started,destroyed; private ScheduledFuture<?> heartbeat; private RpcRequestInitializer initializer;
 public RpcClient(String group,String clientId){this(group,clientId,"ws","127.0.0.1",5612,null);} public RpcClient(String group,String clientId,String host,int port){this(group,clientId,"ws",host,port,null);} public RpcClient(String group,String clientId,String scheme,String host,int port,String token){if(blank(group)||blank(clientId)||blank(host))throw new IllegalArgumentException("group, clientId and host required"); if(!"ws".equals(scheme)&&!"wss".equals(scheme))throw new IllegalArgumentException("scheme must be ws or wss"); this.group=group;this.clientId=clientId;this.scheme=scheme;this.host=host;this.port=port;this.token=token;}
 private static boolean blank(String s){return s==null||s.trim().isEmpty();}
 public RpcClient setupRpcRequestInitializer(RpcRequestInitializer i){initializer=i;return this;} public RpcClient setActionDelay(long d){if(d<0)throw new IllegalArgumentException("actionDelay must not be negative");return this;}
 public void start(){synchronized(lock){if(started||destroyed)return;started=true;if(initializer!=null)initializer.onRpcRequest(null,handlers);} Request.Builder b=new Request.Builder().url(buildWebSocketUrl());if(token!=null&&!token.isEmpty())b.header("Authorization","Bearer "+token);socket=httpClient.newWebSocket(b.build(),listener);}
 public boolean awaitReady(long timeout,TimeUnit unit){try{long end=System.nanoTime()+unit.toNanos(timeout);while(System.nanoTime()<end&&!connected&&!destroyed)Thread.sleep(Math.min(10,Math.max(1,unit.toMillis(10))));return connected&&!destroyed;}catch(InterruptedException e){Thread.currentThread().interrupt();return false;}}
 public boolean isConnected(){return connected;} public void disconnect(){closeSocket();} public void destroy(){synchronized(lock){if(destroyed)return;destroyed=true;}closeSocket();handlers.clear();workers.shutdownNow();scheduler.shutdownNow();httpClient.dispatcher().executorService().shutdown();httpClient.connectionPool().evictAll();} public void destroy(long wait){destroy();try{workers.awaitTermination(wait,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}}
 String buildWebSocketUrl(){try{return scheme+"://"+host+":"+port+"/business/register?"+URLEncoder.encode("protocol_version","UTF-8")+"=1&capabilities="+URLEncoder.encode("invocation_context.v1","UTF-8")+"&group="+URLEncoder.encode(group,"UTF-8")+"&clientId="+URLEncoder.encode(clientId,"UTF-8");}catch(Exception e){throw new IllegalStateException(e);}}
 private final WebSocketListener listener=new WebSocketListener(){public void onOpen(WebSocket w,Response r){if(w!=socket||destroyed){w.close(1000,"stale");return;}} public void onMessage(WebSocket w,String text){if(w!=socket)return;handleMessage(w,text);} public void onClosing(WebSocket w,int c,String s){w.close(c,s);}public void onClosed(WebSocket w,int c,String s){gone(w);}public void onFailure(WebSocket w,Throwable t,Response r){gone(w);}};
 private void handleMessage(WebSocket w,String text){if(text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>MAX_MESSAGE_BYTES){w.close(1009,"message too large");return;} JSONObject m;try{m=JSON.parseObject(text);}catch(Exception e){return;}String type=m.getString("type");if("registered".equals(type)){com.alibaba.fastjson.JSONArray caps=m.getJSONArray("capabilities");if(m.getIntValue("protocol_version")!=1||caps==null||!caps.contains("invocation_context.v1")||connected)return;connected=true;JSONObject bind=identity("bind",null);bind.put("actions",handlers.actionList());send(bind);heartbeat=scheduler.scheduleAtFixedRate(()->send(identity("heartbeat",null)),HEARTBEAT_INTERVAL_MS,HEARTBEAT_INTERVAL_MS,TimeUnit.MILLISECONDS);return;}if(!connected||"heartbeat".equals(type)||"error".equals(type)||"invoke_response".equals(type))return;String seq=m.getString("__sekiro_seq__");if(seq==null)seq=m.getString("sequence");String action=m.getString("action");if(seq==null||action==null)return;RequestHandler h=handlers.get(action);if(h==null){sendFailed(seq,-1,"no handler",m.getString("group"),m.getString("clientId"),m.getString("trace_id"));return;}InvocationContext c;try{c=InvocationContext.fromMessage(m);}catch(Exception e){sendFailed(seq,-1,"invalid invocation context",m.getString("group"),m.getString("clientId"),m.getString("trace_id"));return;}RpcCancellationToken tok=new RpcCancellationToken();activeTokens.add(tok);RpcRequest req=new RpcRequest(m,c,tok);RpcResponse resp=new RpcResponse(this,seq,m.getString("group"),m.getString("clientId"),m.getString("trace_id"));long delay=Math.max(0L,c.getDeadlineUnixMs()-System.currentTimeMillis());ScheduledFuture<?> deadline= c.getDeadlineUnixMs()>0?scheduler.schedule(tok::cancel,delay,TimeUnit.MILLISECONDS):null;workers.execute(()->{try{h.handleRequest(req,resp);}catch(Throwable t){resp.failed(t.getMessage()==null?t.toString():t.getMessage());}finally{activeTokens.remove(tok);if(deadline!=null)deadline.cancel(false);}});}
 private JSONObject identity(String type,Object actions){JSONObject x=new JSONObject();x.put("type",type);x.put("group",group);x.put("clientId",clientId);x.put("timestamp",System.currentTimeMillis());if(actions!=null)x.put("actions",actions);return x;}
 private void send(JSONObject x){WebSocket w=socket;if(connected&&w!=null)w.send(x.toJSONString());} public void sendSuccess(String s,Object d,String g,String id,String t){JSONObject x=base(s,g,id,t);x.put("data",d);x.put("code",0);x.put("status",0);send(x);} public void sendFailed(String s,int st,String m,String g,String id,String t){JSONObject x=base(s,g,id,t);x.put("message",m);x.put("status",st<0?st:-1);send(x);} public void sendStream(String s,String c,boolean done,String e){JSONObject x=base(s,null,null,null);x.put("type","invoke_stream");if(c!=null)x.put("data",c);x.put("done",done);if(e!=null){x.put("error",e);x.put("status",-1);}send(x);}private JSONObject base(String s,String g,String id,String t){JSONObject x=new JSONObject();x.put("__sekiro_seq__",s);if(g!=null)x.put("group",g);if(id!=null)x.put("clientId",id);if(t!=null)x.put("trace_id",t);return x;}
 private void cancelActive(){for(RpcCancellationToken t:activeTokens)t.cancel();}
 private void gone(WebSocket w){synchronized(lock){if(w!=socket)return;connected=false;socket=null;if(heartbeat!=null)heartbeat.cancel(false);heartbeat=null;}cancelActive();}
 private void closeSocket(){WebSocket w; synchronized(lock){connected=false;w=socket;socket=null;if(heartbeat!=null)heartbeat.cancel(false);heartbeat=null;}cancelActive();if(w!=null){w.close(1000,"client closed");w.cancel();}}
}
